#!/usr/bin/env python3
"""Apply the bounded 0020 contacts migration lifecycle hardening.

This script is intentionally one-shot and fail-closed. It verifies the exact
source shape before every transformation and writes the migration only after
all transformations and postconditions have succeeded in memory.
"""

from __future__ import annotations

import base64
from pathlib import Path


PATH = Path("alembic/versions/0020_contacts_hardened.py")


def _decode(value: str) -> str:
    return base64.b64decode(value.encode("ascii")).decode("utf-8")


HELPER = _decode("")
DOWNGRADE = _decode("")
STRICT_TYPES = _decode("")
AUDIT_FK = _decode("")
OLD_UPGRADE_START = _decode("ICAgIG9wID0gX3JiMWw3X3VwZ3JhZGVfb3BlcmF0aW9ucyhnbG9iYWxzKClbIm9wIl0pCiAgICBfcmIxbDdfcHJlcGFyZV8wMDIwX3NoYXJlZF9pbmZyYXN0cnVjdHVyZSgpCiAgICBvcC5leGVjdXRlKCJDUkVBVEUgRVhURU5TSU9OIElGIE5PVCBFWElTVFMgY2l0ZXh0OyIpCgogICAgIyBDcmVhdGUgY3VzdG9tIHR5cGVzIChJREVNUE9URU5UOiBETyAkJC BCRUdJTiAuLi4gRVhDRVBUSU9OIC4uLikK".replace("JC B", "JCB"))
NEW_UPGRADE_START = _decode("ICAgIG9wID0gX3JiMWw3X3VwZ3JhZGVfb3BlcmF0aW9ucyhnbG9iYWxzKClbIm9wIl0pCiAgICBfMDAyMF9wcmVmbGlnaHRfdXBncmFkZV9kb21haW4oKQogICAgX3JiMWw3X3ByZXBhcmVfMDAyMF9zaGFyZWRfaW5mcmFzdHJ1Y3R1cmUoKQoKICAgICMgQ3VzdG9tIHR5cGVzIGFyZSByZXZpc2lvbi1vd25lZDsgY29sbGlzaW9ucyBhcmUgcmVqZWN0ZWQgYnkgcHJlZmxpZ2h0Lgo=")


def require_count(source: str, needle: str, expected: int, label: str) -> None:
    actual = source.count(needle)
    if actual != expected:
        raise SystemExit(
            f"0020 patch {label} drift: expected {expected}, found {actual}"
        )


def main() -> int:
    source = PATH.read_text(encoding="utf-8")
    original = source

    helper_anchor = "# RB1L7_SHARED_INFRASTRUCTURE_HELPERS_END\n\n\n\ndef upgrade():"
    require_count(source, helper_anchor, 1, "helper anchor")
    source = source.replace(helper_anchor, HELPER)

    require_count(source, OLD_UPGRADE_START, 1, "upgrade start")
    source = source.replace(OLD_UPGRADE_START, NEW_UPGRADE_START)

    type_start_marker = (
        '    op.execute("""\n'
        "        DO $$ BEGIN\n"
        "            CREATE TYPE public.contact_kind_enum"
    )
    type_end_marker = (
        "    # ===========================================================================\n"
        "    # SECTION 2: Externally managed cluster-role validation"
    )
    require_count(source, type_start_marker, 1, "type block start")
    require_count(source, type_end_marker, 1, "type block end")
    type_start = source.index(type_start_marker)
    type_end = source.index(type_end_marker, type_start)
    source = source[:type_start] + STRICT_TYPES + source[type_end:]

    replacements = {
        "CREATE TABLE IF NOT EXISTS public.branch_contacts (":
            "CREATE TABLE public.branch_contacts (",
        "CREATE TABLE IF NOT EXISTS public.branch_contacts_audit (":
            "CREATE TABLE public.branch_contacts_audit (",
        "CREATE TABLE IF NOT EXISTS public.branch_contacts_audit_default ":
            "CREATE TABLE public.branch_contacts_audit_default ",
        "CREATE TABLE IF NOT EXISTS app_private.partition_metadata (":
            "CREATE TABLE app_private.partition_metadata (",
    }
    for old, new in replacements.items():
        require_count(source, old, 1, f"strict table {old}")
        source = source.replace(old, new)

    require_count(
        source,
        "CREATE OR REPLACE FUNCTION app_private.",
        9,
        "private function ownership",
    )
    source = source.replace(
        "CREATE OR REPLACE FUNCTION app_private.",
        "CREATE FUNCTION app_private.",
    )

    require_count(
        source,
        "CONCURRENTLY IF NOT EXISTS",
        10,
        "static concurrent indexes",
    )
    source = source.replace("CONCURRENTLY IF NOT EXISTS", "CONCURRENTLY")

    for index_name in (
        "ix_audit_contact",
        "ix_audit_branch_contacts_ordered",
        "ix_audit_org_changed",
    ):
        old = f"CREATE INDEX IF NOT EXISTS {index_name}"
        new = f"CREATE INDEX {index_name}"
        require_count(source, old, 1, f"static audit index {index_name}")
        source = source.replace(old, new)

    audit_fk_anchor = "    # Default partition for seamless insertions\n"
    require_count(source, audit_fk_anchor, 1, "audit FK anchor")
    source = source.replace(audit_fk_anchor, AUDIT_FK + audit_fk_anchor)

    downgrade_start = source.index("def downgrade():")
    source = source[:downgrade_start] + DOWNGRADE

    if source == original:
        raise SystemExit("0020 patch made no changes")

    upgrade = source[source.index("def upgrade():"):source.index("def downgrade():")]
    downgrade = source[source.index("def downgrade():"):]

    forbidden_upgrade = (
        "CREATE EXTENSION IF NOT EXISTS citext",
        "CREATE OR REPLACE FUNCTION app_private.",
        "CREATE TABLE IF NOT EXISTS public.branch_contacts",
        "CREATE TABLE IF NOT EXISTS public.branch_contacts_audit",
        "CREATE TABLE IF NOT EXISTS app_private.partition_metadata",
    )
    for item in forbidden_upgrade:
        if item in upgrade:
            raise SystemExit(f"0020 patch postcondition failed: {item}")

    if "CASCADE" in downgrade:
        raise SystemExit("0020 downgrade still contains CASCADE")
    if "IF EXISTS" in downgrade:
        raise SystemExit("0020 downgrade still masks missing objects")
    if downgrade.count(" RESTRICT;") != 16:
        raise SystemExit(
            "0020 strict-drop count drift: "
            f"{downgrade.count(' RESTRICT;')}"
        )

    required = (
        "_0020_preflight_upgrade_domain()",
        "_0020_preflight_downgrade_domain()",
        "fk_branch_contacts_audit_org",
        "0020 requires infrastructure-owned citext",
        "DROP TABLE public.branch_contacts_audit RESTRICT",
        "DROP TYPE public.contact_kind_enum RESTRICT",
    )
    for item in required:
        if item not in source:
            raise SystemExit(f"0020 patch required contract missing: {item}")

    compile(source, str(PATH), "exec")
    PATH.write_text(source, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
